create or replace function public.settle_booking_confirmation(_booking_id uuid,_decline boolean default false) returns text language plpgsql security definer set search_path=public as $$ declare b public.bookings; is_venue boolean; is_artist boolean; new_status text; begin select * into b from public.bookings where id=_booking_id for update; if not found then raise exception 'Booking not found'; end if; is_venue:=public.owns_party('venue',b.venue_id); is_artist:=public.owns_party('artist',b.artist_id); if not(is_venue or is_artist) then raise exception 'Not part of this booking'; end if; if b.status<>'negotiating' then raise exception 'This booking is already settled'; end if; if _decline then new_status:='cancelled'; else if b.gig_date is null or b.start_time is null or b.set_length_min is null or b.set_length_min<=0 or b.offer_usd is null or b.offer_usd<=0 then raise exception 'Agree on date, time, set length and pay first'; end if; b.venue_confirmed:=b.venue_confirmed or is_venue; b.artist_confirmed:=b.artist_confirmed or is_artist; new_status:=case when b.venue_confirmed and b.artist_confirmed then 'confirmed' else 'negotiating' end; end if; update public.bookings set status=new_status,venue_confirmed=b.venue_confirmed,artist_confirmed=b.artist_confirmed where id=_booking_id; insert into public.messages(thread_id,sender_role,content) select id,'agent',case when _decline then 'This booking has been cancelled.' when new_status='confirmed' then 'Both sides confirmed. The venue can now pay and hold.' else 'One side confirmed. Waiting on the other side.' end from public.threads where booking_id=_booking_id; return new_status; end $$;
revoke all on function public.settle_booking_confirmation(uuid,boolean) from public; grant execute on function public.settle_booking_confirmation(uuid,boolean) to authenticated,service_role;
revoke update on public.artists from authenticated; grant update(name,birthday,background,genres,borough,email,phone,video_path,photo_path,start_date,set_length_min,rate_usd,goals) on public.artists to authenticated;
revoke update on public.venues from authenticated; grant update(name,venue_type,address,borough,genres,contact_name,email,phone,photo_path,start_date,set_length_min,budget_usd,capacity,goals) on public.venues to authenticated;
create unique index one_booking_per_suggestion on public.bookings(suggestion_id) where suggestion_id is not null;